function styleFor(style: PatternStyle, density: PatternDensity): CSSProperties {
  const bg = "var(--background)";
  // Ink follows the accent (fallback: tint hue) so every geometric pattern recolors with the accent knob.
  const ink = "oklch(0.6 0.16 var(--accent-h, var(--glass-tint-h)) / 0.5)";
  // Density scales the tile size for every pattern.
  const d = DENSITY_SCALE[density];
  const px = (n: number) => `${Math.round(n * d)}px`;
  const sq = (n: number) => `${px(n)} ${px(n)}`;

  switch (style) {
    case "grid":
      return {
        backgroundColor: bg,
        backgroundImage: `linear-gradient(${ink} 1px, transparent 1px), linear-gradient(90deg, ${ink} 1px, transparent 1px)`,
        backgroundSize: sq(44),
      };
    case "dots":
      return {
        backgroundColor: bg,
        backgroundImage: `radial-gradient(${ink} 1.6px, transparent 1.8px)`,
        backgroundSize: sq(24),
      };
    case "mesh": {
      // Mesh blobs center on the accent (hue + vividness) when it's on, else the tint's content hue —
      // rotated 0/90/180/270 for a full spread.
      const mh = "var(--accent-h, var(--glass-tint-h))";
      const mc = "var(--accent-c, 0.16)";
      return {
        backgroundColor: bg,
        backgroundImage: `radial-gradient(40% 40% at 15% 20%, oklch(0.65 ${mc} ${mh} / 0.5) 0, transparent 100%), radial-gradient(40% 40% at 85% 15%, oklch(0.65 ${mc} calc(${mh} + 90) / 0.5) 0, transparent 100%), radial-gradient(45% 45% at 22% 85%, oklch(0.65 ${mc} calc(${mh} + 180) / 0.5) 0, transparent 100%), radial-gradient(40% 40% at 82% 82%, oklch(0.65 ${mc} calc(${mh} + 270) / 0.5) 0, transparent 100%)`,
      };
    }
    case "starfield":
      // Rendered by its own branch in PatternBackground (day/night palettes live in STARFIELD_STYLES'
      // [data-pattern] var blocks); kept exhaustive here.
      return {
        backgroundColor: "oklch(0.19 0.055 var(--accent-h, var(--glass-tint-h)))",
      };
    case "synthwave":
      // Rendered by its own multi-layer branch in PatternBackground (day/night palettes live in
      // SYNTHWAVE_STYLES' [data-pattern] var blocks); keeps the switch exhaustive.
      return {
        backgroundColor: "oklch(0.09 0.03 282)",
      };
    case "moonrise":
      // Rendered alongside synthwave in PatternBackground's shared branch (palettes in SYNTHWAVE_STYLES);
      // kept exhaustive here.
      return {
        backgroundColor: "oklch(0.07 0.03 270)",
      };
    case "chase":
      // Pac-Man chase is rendered by its own branch in PatternBackground; kept exhaustive here.
      return {
        backgroundColor: "oklch(0.12 0.025 var(--glass-tint-h))",
      };
  }
}

/** A full-viewport, pure-CSS pattern wallpaper. Recolors with the live tint; sprites tile a field. */
export function PatternBackground({
  style = "dots",
  density = "medium",
  speed = 8,
  disc = "right",
}: {
  style?: PatternStyle;
  density?: PatternDensity;
  speed?: number;
  disc?: "left" | "center" | "right";
}) {
  // Animated patterns share one pace: --pat-dur (loop seconds) + --pat-play (paused when speed is 0/static).
  const patDur = speed > 0 ? `${speed}s` : "8s";
  const patPlay = speed > 0 ? "running" : "paused";
  // Sun/moon horizontal placement for the horizon scenes (off-center clears centered page content).
  const discX = {
    left: "26%",
    center: "50%",
    right: "74%",
  }[disc];
  if (style === "chase") {
    return (
      <div
        className="fixed inset-0 -z-10 overflow-hidden pointer-events-none transition-[background-color] duration-500"
        style={
          {
            "--pat-dur": patDur,
            "--pat-play": patPlay,
            "--pac-cell": `${Math.round(34 * DENSITY_SCALE[density])}px`,
          } as CSSProperties
        }
        data-pattern="chase"
      >
        <style>{PAC_STYLES}</style>
        <div className="pac-scene">
          <div className="pac-field" />
          {PAC_WALLS.map((w) => (
            <div
              key={`${w.top}-${w.left}`}
              className="pac-wall"
              style={{
                top: w.top,
                left: w.left,
                width: w.w,
                height: w.h,
              }}
            />
          ))}
          {PAC_LANES.map((lane) => (
            <div
              key={lane.top}
              className="pac-lane"
              style={
                {
                  // Snap the nominal % to the nearest pellet-row CENTER below it (rows sit at (k+0.5)·cell),
                  // so Pac chomps along an actual dot line at every density and viewport.
                  top: `calc(round(down, ${lane.top}, var(--pac-cell, 34px)) + var(--pac-cell, 34px) / 2)`,
                  "--pac-dur": `calc(var(--pat-dur, 8s) * ${lane.factor})`,
                  "--pac-ghost": `oklch(0.68 0.19 ${lane.hue})`,
                  "--pac-fright-dur": lane.frightDur,
                  "--pac-delay": lane.delay,
                } as CSSProperties
              }
            >
              <div className={lane.caught ? "pac-ghost-runner pac-caught" : "pac-ghost-runner"}>
                <div className="pac-ghost" />
              </div>
              <div className="pac-runner">
                <div className="pac-wake" />
                <div className="pac-man" />
              </div>
            </div>
          ))}
          {PAC_VLANES.map((lane) => (
            <div
              key={lane.left}
              className={lane.up ? "pac-vlane pac-vup" : "pac-vlane"}
              style={
                {
                  // Same pellet-grid snap as the E–W lanes, along the x axis (columns at (k+0.5)·cell).
                  left: `calc(round(down, ${lane.left}, var(--pac-cell, 34px)) + var(--pac-cell, 34px) / 2)`,
                  "--pac-dur": `calc(var(--pat-dur, 8s) * ${lane.factor})`,
                  "--pac-ghost": `oklch(0.68 0.19 ${lane.hue})`,
                  "--pac-fright-dur": lane.frightDur,
                  "--pac-delay": lane.delay,
                } as CSSProperties
              }
            >
              <div className={lane.caught ? "pac-vghost-runner pac-caught" : "pac-vghost-runner"}>
                <div className="pac-vghost" />
              </div>
              <div className="pac-vrunner">
                <div className="pac-vwake" />
                <div className="pac-vman" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }
  if (style === "synthwave" || style === "moonrise") {
    const stars = STAR_GRADIENTS.slice(0, STAR_COUNT[density]).join(", ");
    const moon = style === "moonrise";
    return (
      <div
        className="fixed inset-0 -z-10 overflow-hidden pointer-events-none transition-[background-color] duration-500"
        style={
          {
            // Scene colors (incl. --sw-line) live in SYNTHWAVE_STYLES' [data-pattern] palette blocks so the
            // .dark day/night switch can override them — an inline declaration would beat every stylesheet rule.
            // Sun/moon horizontal placement (left/center/right).
            "--sw-disc-x": discX,
            // Grid scroll pace — one cell every --pat-dur seconds (shared pace across animated patterns).
            "--pat-dur": patDur,
            "--pat-play": patPlay,
          } as CSSProperties
        }
        data-pattern={style}
      >
        <style>{SYNTHWAVE_STYLES}</style>
        <div className="sw-scene">
          <div
            className="sw-stars"
            style={{
              backgroundImage: stars,
            }}
          />
          <MuseConstellation />
          <div className={moon ? "sw-moon" : "sw-sun"} />
          <div className="sw-ground" />
          <div className="sw-glow" />
          <div className="sw-floor sw-floor-rungs">
            <div className="sw-grid sw-grid-rungs" />
          </div>
          <div className="sw-floor sw-floor-rails">
            <div className="sw-grid sw-grid-rails" />
          </div>
        </div>
      </div>
    );
  }
  if (style === "starfield") {
    // Scene colors live in STARFIELD_STYLES' palette blocks (an inline background would beat the .dark
    // day/night flip); only the star GLINTS — white in both modes — are painted inline, on their own
    // layer so the palette's --sw-stars-o can dim them by day.
    const stars = STAR_GRADIENTS.slice(0, STAR_COUNT[density]).join(", ");
    return (
      <div className="fixed inset-0 -z-10 overflow-hidden pointer-events-none transition-[background-color] duration-500" data-pattern="starfield">
        <style>{STARFIELD_STYLES}</style>
        <div className="sf-scene" />
        <div
          className="sf-stars"
          style={{
            backgroundImage: stars,
          }}
        />
        <MuseConstellation />
      </div>
    );
  }
  return (
    <div
      className="fixed inset-0 -z-10 pointer-events-none transition-[background-color] duration-500"
      style={styleFor(style, density)}
      data-pattern={style}
    />
  );
}

"use client";

import * as React from "react";
import { type CanvasRamp, type CanvasStyle, createCanvas, FRESCO_HUES } from "@/lib/canvas-background-utils";

interface CanvasBackgroundProps {
  /** Canvas style: gradient | lava | circle. */
  style?: CanvasStyle;
  /** Hue override (deg). When set, drives the canvas color instead of the live --glass-tint-h. */
  hue?: number;
  /** Ramp axis the colors follow (lightness = "linear"). */
  ramp?: CanvasRamp;
  /** Steps per side (4–12). */
  steps?: number;
  /** Gradient angle in degrees (gradient style). */
  angle?: number;
  /** Animation pace (0 = static). */
  speed?: number;
  /** Whether to animate. */
  animated?: boolean;
  /** Seed for deterministic placement. */
  seed?: string;
  className?: string;
  /** Opacity of the background (0–1). */
  opacity?: number;
  /** Blur the canvas. */
  blur?: boolean;
}

export function CanvasBackground({
  style: canvasStyle = "gradient",
  hue,
  ramp = "tonal",
  steps = 6,
  angle = 90,
  speed = 1,
  animated = false,
  seed,
  className = "",
  opacity = 1,
  blur = false,
}: CanvasBackgroundProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const frameRef = React.useRef<number | undefined>(undefined);
  const [dimensions, setDimensions] = React.useState({
    width: 1920,
    height: 1080,
    dpr: 1,
  });
  // Live base color tracks the glass tint, so the canvas recolors with the theme (like the CSS
  // gradient background).
  const [tint, setTint] = React.useState<{
    hue: number;
    dark: boolean;
    preset: string | undefined;
  }>({
    hue: 250,
    dark: true,
    preset: undefined,
  });

  React.useEffect(() => {
    const update = () => {
      // Back the canvas at device resolution (capped 2×) so it isn't upscaled/blurry on HiDPI.
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      setDimensions({
        width: Math.round(window.innerWidth * dpr),
        height: Math.round(window.innerHeight * dpr),
        dpr,
      });
    };
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);

  React.useEffect(() => {
    const root = document.documentElement;
    const read = () => {
      const cs = getComputedStyle(root);
      const acc = Number.parseFloat(cs.getPropertyValue("--accent-h"));
      // Honor the accent hue when the accent knob is on, else the live tint hue.
      const v = Number.isFinite(acc) ? acc : Number.parseFloat(cs.getPropertyValue("--glass-tint-h"));
      const next = {
        hue: Number.isFinite(v) ? v : 250,
        dark: root.classList.contains("dark"),
        preset: root.dataset.glassTint,
      };
      setTint((prev) => (prev.hue === next.hue && prev.dark === next.dark && prev.preset === next.preset ? prev : next));
    };
    read();
    const observer = new MutationObserver(read);
    observer.observe(root, {
      attributes: true,
      attributeFilter: [
        "class",
        "data-glass-tint",
        "style",
      ],
    });
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d", {
      colorSpace: "display-p3",
    });
    if (!ctx) return;
    canvas.width = dimensions.width;
    canvas.height = dimensions.height;

    const p3 = window.matchMedia?.("(color-gamut: p3)").matches ?? false;
    // Center color tracks the theme so it doesn't blast bright on dark / wash out on light.
    const base = {
      l: tint.dark ? 52 : 72,
      c: 0.15,
      h: hue ?? tint.hue,
    };
    // A fresco tint (sistine/muse/…) feeds its multi-hue palette at the canvas's standard L/C, so the
    // canvas matches the fresco glass instead of using just its base hue. The `hue` prop override wins.
    const frescoHues = hue == null && tint.preset ? FRESCO_HUES[tint.preset] : undefined;
    const colors = frescoHues?.map((h) => `oklch(${tint.dark ? 52 : 72}% 0.15 ${h})`);
    const { step } = createCanvas({
      width: dimensions.width,
      height: dimensions.height,
      dpr: dimensions.dpr,
      color: base,
      colors,
      style: canvasStyle,
      ramp,
      steps,
      angle,
      speed,
      p3,
      seed: seed || window.location.pathname,
    });

    if (animated && speed > 0) {
      let last = 0;
      const paint = (now: number) => {
        frameRef.current = requestAnimationFrame(paint);
        // ~30fps cap — the gradient repaint / gooey blur are costly and the motion is slow.
        if (now - last < 33) return;
        last = now;
        step(ctx, now / 1000);
      };
      frameRef.current = requestAnimationFrame(paint);
    } else {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      step(ctx, 0);
    }

    return () => {
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
    };
  }, [
    dimensions,
    tint,
    hue,
    canvasStyle,
    ramp,
    steps,
    angle,
    speed,
    animated,
    seed,
  ]);

  return (
    <canvas
      ref={canvasRef}
      className={`fixed inset-0 -z-10 pointer-events-none ${className}`}
      style={{
        opacity,
        filter: blur ? "blur(20px)" : "none",
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
      }}
    />
  );
}

"use client";

import * as React from "react";
import { FRESCO_HUES } from "@/lib/canvas-background-utils";
import { type GradientGeometry, type GradientShape, type RampGradientAxis, rampGradient, wrapGradient } from "@/lib/oklch-utils";

/**
 * A ramp-driven gradient wallpaper. The gradient is one of our oklch ramps (hue / lightness / tonal
 * / chroma) centered on the live glass-tint color (so it recolors with the theme) with the center as a
 * slightly wider plateau, painted as a `linear`, `radial`, or `conic` gradient. Pure CSS — crisp at any DPI.
 */
export function GradientBackground({
  axis = "tonal",
  hue,
  angle = 90,
  shape = "linear",
  position,
  radialShape,
  radialSize,
}: {
  axis?: RampGradientAxis;
  /** Hue override (deg). When set, drives the gradient color instead of the live --glass-tint-h. */
  hue?: number;
  angle?: number;
  shape?: GradientShape;
} & GradientGeometry) {
  const [{ hue: tintHue, dark, p3, preset }, setState] = React.useState<{
    hue: number;
    dark: boolean;
    p3: boolean;
    preset: string | undefined;
  }>({
    hue: 250,
    dark: true,
    p3: false,
    preset: undefined,
  });

  React.useEffect(() => {
    const root = document.documentElement;
    const read = () => {
      const cs = getComputedStyle(root);
      const acc = Number.parseFloat(cs.getPropertyValue("--accent-h"));
      // Honor the accent hue when the accent knob is on, else the live tint hue.
      const v = Number.isFinite(acc) ? acc : Number.parseFloat(cs.getPropertyValue("--glass-tint-h"));
      const next = {
        hue: Number.isFinite(v) ? v : 250,
        dark: root.classList.contains("dark"),
        p3: window.matchMedia?.("(color-gamut: p3)").matches ?? false,
        preset: root.dataset.glassTint,
      };
      setState((prev) => (prev.hue === next.hue && prev.dark === next.dark && prev.p3 === next.p3 && prev.preset === next.preset ? prev : next));
    };
    read();
    // Recolor on theme (class) + tint (preset attribute / custom inline vars) changes.
    const observer = new MutationObserver(read);
    observer.observe(root, {
      attributes: true,
      attributeFilter: [
        "class",
        "data-glass-tint",
        "style",
      ],
    });
    return () => observer.disconnect();
  }, []);

  // Center lightness tracks the theme so it doesn't blast bright on dark / wash out on light. A fresco
  // tint lays its multi-hue palette across the gradient (same L/C) so it matches the fresco glass.
  const l = dark ? 52 : 72;
  // An explicit `hue` prop overrides the fresco palette + live tint (mirrors CanvasBackground's `hue`).
  const frescoHues = hue == null && preset ? FRESCO_HUES[preset] : undefined;
  const gradient = frescoHues
    ? wrapGradient(shape, frescoHues.map((h) => `oklch(${l}% 0.15 ${h})`).join(", "), {
        angle,
        position,
        radialShape,
        radialSize,
      })
    : rampGradient(
        axis,
        {
          l,
          c: 0.15,
          h: hue ?? tintHue,
        },
        5,
        {
          angle,
          gamut: p3 ? "p3" : "srgb",
          shape,
          position,
          radialShape,
          radialSize,
        },
      );

  return (
    <div
      className="fixed inset-0 -z-10 pointer-events-none transition-[background] duration-500"
      style={{
        background: gradient,
      }}
    >
      {/* Subtle organic highlight/shadow for depth on top of the flat ramp. */}
      <div
        className="absolute inset-0"
        style={{
          background:
            "radial-gradient(circle at 20% 25%, oklch(var(--shadow-highlight) / 0.12) 0%, transparent 45%), radial-gradient(circle at 80% 75%, oklch(var(--shadow-ink) / 0.12) 0%, transparent 45%)",
          mixBlendMode: "overlay",
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { CanvasBackground } from "@/components/canvas-background";
import { GradientBackground } from "@/components/gradient-background";
import { PATTERN_DENSITIES, PATTERN_STYLES, PatternBackground, type PatternDensity, type PatternStyle } from "@/components/pattern-background";
import type { CanvasStyle } from "@/lib/canvas-background-utils";
import type { GradientGeometry, GradientShape, RampGradientAxis } from "@/lib/oklch-utils";

export type BackgroundType = "gradient" | "canvas" | "pattern" | "none";

const STORAGE_KEY = "sistine-background";

/** Canvas styles (lava renamed from "blobs", circle from "circles"). */
export const CANVAS_STYLES: CanvasStyle[] = [
  "gradient",
  "lava",
  "circle",
];

/** Ramp axes shared by the Gradient background and the Canvas (lightness = the "linear" ramp). */
export const RAMP_AXES: RampGradientAxis[] = [
  "tonal",
  "hue",
  "lightness",
  "chroma",
];

/** Gradient painting shapes the Gradient background cycles through. */
export const GRADIENT_SHAPES: GradientShape[] = [
  "linear",
  "radial",
  "conic",
];

/** Center positions (radial + conic) the switcher cycles through. */
export const GRADIENT_POSITIONS: {
  value: string;
  label: string;
}[] = [
  {
    value: "50% 50%",
    label: "center",
  },
  {
    value: "0% 0%",
    label: "top-left",
  },
  {
    value: "100% 0%",
    label: "top-right",
  },
  {
    value: "100% 100%",
    label: "bottom-right",
  },
  {
    value: "0% 100%",
    label: "bottom-left",
  },
];

/** Radial shape + size options. */
export const RADIAL_SHAPES: NonNullable<GradientGeometry["radialShape"]>[] = [
  "circle",
  "ellipse",
];
export const RADIAL_SIZES: NonNullable<GradientGeometry["radialSize"]>[] = [
  "farthest-corner",
  "farthest-side",
  "closest-corner",
  "closest-side",
];

/** Steps-per-side presets the canvas/ramps cycle through (4–12). */
export const CANVAS_STEPS = [
  4,
  6,
  8,
  10,
  12,
] as const;

/** Animation pace presets. */
export const CANVAS_SPEEDS = [
  0.5,
  1,
  2,
] as const;

/** Animated-pattern pace: loop/scroll duration in SECONDS (2s fastest … 16s slowest); 0 = static.
 * Shared by every animated pattern (ghost, synthwave, moonrise, chase) via the --pat-dur CSS var. */
export const PATTERN_SPEEDS = [
  2,
  4,
  8,
  12,
  16,
  0,
] as const;

/** Sun/moon horizontal placement for the horizon scenes (synthwave / moonrise) — off-center clears the
 * page's centered content. */
export const PATTERN_DISCS = [
  "right",
  "center",
  "left",
] as const;

function persistBackground(next: BackgroundType) {
  try {
    localStorage.setItem(STORAGE_KEY, next);
  } catch {
    // ignore storage failures (private mode, etc.)
  }
}

function pickRandom<T>(items: readonly T[]): T {
  return items[Math.floor(Math.random() * items.length)];
}

function cycle<T>(items: readonly T[], current: T): T {
  const i = items.indexOf(current);
  return items[(i + 1) % items.length];
}

interface BackgroundContextValue {
  background: BackgroundType;
  setBackground: (background: BackgroundType) => void;
  /** The ramp axis driving the gradient background. */
  gradientAxis: RampGradientAxis;
  /** Switch to the gradient background and set its ramp axis. */
  setGradientAxis: (axis: RampGradientAxis) => void;
  /** Gradient angle in degrees (90 = left → right). */
  gradientAngle: number;
  /** Rotate the gradient by 45°. */
  cycleGradientAngle: () => void;
  /** The gradient painting shape (linear | radial | conic). */
  gradientShape: GradientShape;
  /** Advance to the next gradient shape. */
  cycleGradientShape: () => void;
  /** Center position for radial + conic gradients (CSS `at <position>`). */
  gradientPosition: string;
  /** Advance to the next center-position preset. */
  cycleGradientPosition: () => void;
  /** Radial shape (circle | ellipse). */
  radialShape: NonNullable<GradientGeometry["radialShape"]>;
  /** Toggle the radial shape. */
  cycleRadialShape: () => void;
  /** Radial size keyword. */
  radialSize: NonNullable<GradientGeometry["radialSize"]>;
  /** Advance to the next radial size. */
  cycleRadialSize: () => void;
  // ── Canvas ──
  /** The canvas style (gradient | lava | circle). */
  canvasStyle: CanvasStyle;
  /** Switch to the canvas background and set its style. */
  setCanvasStyle: (style: CanvasStyle) => void;
  /** The ramp axis driving the canvas colors. */
  canvasRamp: RampGradientAxis;
  /** Switch to the canvas background and set its ramp axis. */
  setCanvasRamp: (axis: RampGradientAxis) => void;
  /** Steps per side (4–12). */
  canvasSteps: number;
  /** Advance to the next steps-per-side preset. */
  cycleCanvasSteps: () => void;
  /** Canvas gradient angle in degrees. */
  canvasAngle: number;
  /** Rotate the canvas gradient by 45°. */
  cycleCanvasAngle: () => void;
  /** Canvas animation pace. */
  canvasSpeed: number;
  /** Advance to the next animation-pace preset. */
  cycleCanvasSpeed: () => void;
  /** Whether the canvas is currently animating. */
  canvasAnimated: boolean;
  /** Toggle canvas animation on/off. */
  toggleCanvasAnimated: () => void;
  /** Switch to the canvas background and reshuffle it (new style + ramp + layout seed). */
  shuffleCanvas: () => void;
  // ── Pattern (pure-CSS wallpapers) ──
  /** The active CSS pattern style. */
  patternStyle: PatternStyle;
  /** Switch to the pattern background and set its style. */
  setPatternStyle: (style: PatternStyle) => void;
  /** Advance to the next pattern style. */
  cyclePatternStyle: () => void;
  /** Star-field density (sparse | medium | dense). */
  patternDensity: PatternDensity;
  /** Advance to the next star-field density. */
  cyclePatternDensity: () => void;
  /** Horizon-grid scroll pace (synthwave / moonrise); 0 is static. */
  patternSpeed: number;
  /** Advance to the next grid scroll pace (… → static). */
  cyclePatternSpeed: () => void;
  /** Sun/moon placement for the horizon scenes (right | center | left). */
  patternDisc: (typeof PATTERN_DISCS)[number];
  /** Advance to the next sun/moon placement. */
  cyclePatternDisc: () => void;
  // ── Base color (the "none" backdrop) ──
  /** Base color for the "none" backdrop; null = follow the theme (tint-tinted, light/dark aware). */
  baseColor: string | null;
  /** Override the "none" backdrop color; null clears back to the themed default. */
  setBaseColor: (color: string | null) => void;
}

const BackgroundContext = React.createContext<BackgroundContextValue | null>(null);

export function useBackground() {
  const context = React.useContext(BackgroundContext);
  if (!context) {
    throw new Error("useBackground must be used within a BackgroundProvider");
  }
  return context;
}

interface RenderArgs {
  gradientAxis: RampGradientAxis;
  gradientAngle: number;
  gradientShape: GradientShape;
  gradientPosition: string;
  radialShape: NonNullable<GradientGeometry["radialShape"]>;
  radialSize: NonNullable<GradientGeometry["radialSize"]>;
  canvasStyle: CanvasStyle;
  canvasRamp: RampGradientAxis;
  canvasSteps: number;
  canvasAngle: number;
  canvasSpeed: number;
  canvasAnimated: boolean;
  canvasSeed: string;
  patternStyle: PatternStyle;
  patternDensity: PatternDensity;
  patternSpeed: number;
  patternDisc: (typeof PATTERN_DISCS)[number];
  baseColor: string | null;
}

function renderBackground(background: BackgroundType, args: RenderArgs) {
  switch (background) {
    case "canvas":
      // key forces a clean redraw when the style/ramp/steps/seed/animation change
      return (
        <CanvasBackground
          key={`${args.canvasStyle}-${args.canvasRamp}-${args.canvasSteps}-${args.canvasAngle}-${args.canvasSpeed}-${args.canvasSeed}-${args.canvasAnimated}`}
          style={args.canvasStyle}
          ramp={args.canvasRamp}
          steps={args.canvasSteps}
          angle={args.canvasAngle}
          speed={args.canvasSpeed}
          animated={args.canvasAnimated}
          seed={args.canvasSeed}
        />
      );
    case "pattern":
      return <PatternBackground style={args.patternStyle} density={args.patternDensity} speed={args.patternSpeed} disc={args.patternDisc} />;
    case "none":
      // Forgo the decorative backdrop — a clean solid that honors the theme (tint hue, light/dark) by
      // default, overridable by the user's chosen base color.
      return (
        <>
          <style>{`[data-bg-none]{background:oklch(0.98 0.006 var(--glass-tint-h))}.dark [data-bg-none]{background:oklch(0.15 0.014 var(--glass-tint-h))}`}</style>
          <div
            className="fixed inset-0 -z-10 transition-[background-color] duration-500"
            data-bg-none=""
            style={
              args.baseColor
                ? {
                    background: args.baseColor,
                  }
                : undefined
            }
          />
        </>
      );
    default:
      return (
        <GradientBackground
          axis={args.gradientAxis}
          angle={args.gradientAngle}
          shape={args.gradientShape}
          position={args.gradientPosition}
          radialShape={args.radialShape}
          radialSize={args.radialSize}
        />
      );
  }
}

/**
 * Holds the site-wide background choice (persisted to localStorage) and renders it
 * behind the app. Pair with <BackgroundSwitcher /> to preview + tune each style.
 */
export function BackgroundProvider({ children }: { children: React.ReactNode }) {
  // SSR + first client render use "gradient" so hydration matches; localStorage is read after mount.
  const [background, setBackgroundState] = React.useState<BackgroundType>("gradient");
  const [gradientAxis, setGradientAxisState] = React.useState<RampGradientAxis>("tonal");
  const [gradientAngle, setGradientAngle] = React.useState(90);
  const [gradientShape, setGradientShape] = React.useState<GradientShape>("linear");
  const [gradientPosition, setGradientPosition] = React.useState("50% 50%");
  const [radialShape, setRadialShape] = React.useState<NonNullable<GradientGeometry["radialShape"]>>("circle");
  const [radialSize, setRadialSize] = React.useState<NonNullable<GradientGeometry["radialSize"]>>("farthest-corner");
  const [canvasStyle, setCanvasStyleState] = React.useState<CanvasStyle>("gradient");
  const [canvasRamp, setCanvasRampState] = React.useState<RampGradientAxis>("tonal");
  const [canvasSteps, setCanvasSteps] = React.useState(6);
  const [canvasAngle, setCanvasAngle] = React.useState(90);
  const [canvasSpeed, setCanvasSpeed] = React.useState(1);
  const [canvasAnimated, setCanvasAnimated] = React.useState(false);
  const [canvasSeed, setCanvasSeed] = React.useState("sistine");
  const [patternStyle, setPatternStyleState] = React.useState<PatternStyle>("dots");
  const [patternDensity, setPatternDensityState] = React.useState<PatternDensity>("medium");
  const [patternSpeed, setPatternSpeed] = React.useState<number>(8);
  const [baseColor, setBaseColorState] = React.useState<string | null>(null);
  const [patternDisc, setPatternDisc] = React.useState<(typeof PATTERN_DISCS)[number]>("right");

  React.useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === "gradient" || stored === "canvas" || stored === "pattern" || stored === "none") {
      setBackgroundState(stored);
    }
  }, []);

  const setBackground = React.useCallback((next: BackgroundType) => {
    setBackgroundState(next);
    persistBackground(next);
  }, []);

  const setBaseColor = React.useCallback((color: string | null) => {
    setBaseColorState(color);
  }, []);

  const setGradientAxis = React.useCallback((axis: RampGradientAxis) => {
    setBackgroundState("gradient");
    setGradientAxisState(axis);
    persistBackground("gradient");
  }, []);

  const cycleGradientAngle = React.useCallback(() => {
    setGradientAngle((a) => (a + 45) % 360);
  }, []);

  const cycleGradientShape = React.useCallback(() => {
    setGradientShape((s) => cycle(GRADIENT_SHAPES, s));
  }, []);

  const cycleGradientPosition = React.useCallback(() => {
    setGradientPosition((p) => {
      const i = GRADIENT_POSITIONS.findIndex((x) => x.value === p);
      return GRADIENT_POSITIONS[(i + 1) % GRADIENT_POSITIONS.length].value;
    });
  }, []);

  const cycleRadialShape = React.useCallback(() => {
    setRadialShape((s) => cycle(RADIAL_SHAPES, s));
  }, []);

  const cycleRadialSize = React.useCallback(() => {
    setRadialSize((s) => cycle(RADIAL_SIZES, s));
  }, []);

  const setCanvasStyle = React.useCallback((style: CanvasStyle) => {
    setBackgroundState("canvas");
    setCanvasStyleState(style);
    persistBackground("canvas");
  }, []);

  const setCanvasRamp = React.useCallback((axis: RampGradientAxis) => {
    setBackgroundState("canvas");
    setCanvasRampState(axis);
    persistBackground("canvas");
  }, []);

  const cycleCanvasSteps = React.useCallback(() => {
    setCanvasSteps((s) => cycle(CANVAS_STEPS, s as (typeof CANVAS_STEPS)[number]));
  }, []);

  const cycleCanvasAngle = React.useCallback(() => {
    setCanvasAngle((a) => (a + 45) % 360);
  }, []);

  const cycleCanvasSpeed = React.useCallback(() => {
    setCanvasSpeed((s) => cycle(CANVAS_SPEEDS, s as (typeof CANVAS_SPEEDS)[number]));
  }, []);

  const toggleCanvasAnimated = React.useCallback(() => {
    setCanvasAnimated((on) => !on);
  }, []);

  const shuffleCanvas = React.useCallback(() => {
    setBackgroundState("canvas");
    setCanvasStyleState(pickRandom(CANVAS_STYLES));
    setCanvasRampState(pickRandom(RAMP_AXES));
    setCanvasSeed(Math.random().toString(36).slice(2));
    persistBackground("canvas");
  }, []);

  const setPatternStyle = React.useCallback((style: PatternStyle) => {
    setBackgroundState("pattern");
    setPatternStyleState(style);
    persistBackground("pattern");
  }, []);

  const cyclePatternStyle = React.useCallback(() => {
    setBackgroundState("pattern");
    setPatternStyleState((s) => cycle(PATTERN_STYLES, s));
    persistBackground("pattern");
  }, []);

  const cyclePatternDensity = React.useCallback(() => {
    setBackgroundState("pattern");
    setPatternDensityState((d) => cycle(PATTERN_DENSITIES, d));
    persistBackground("pattern");
  }, []);

  const cyclePatternSpeed = React.useCallback(() => {
    setBackgroundState("pattern");
    setPatternSpeed((s) => cycle(PATTERN_SPEEDS, s as (typeof PATTERN_SPEEDS)[number]));
    persistBackground("pattern");
  }, []);

  const cyclePatternDisc = React.useCallback(() => {
    setBackgroundState("pattern");
    setPatternDisc((d) => cycle(PATTERN_DISCS, d));
    persistBackground("pattern");
  }, []);

  const value = React.useMemo(
    () => ({
      background,
      setBackground,
      gradientAxis,
      setGradientAxis,
      gradientAngle,
      cycleGradientAngle,
      gradientShape,
      cycleGradientShape,
      gradientPosition,
      cycleGradientPosition,
      radialShape,
      cycleRadialShape,
      radialSize,
      cycleRadialSize,
      canvasStyle,
      setCanvasStyle,
      canvasRamp,
      setCanvasRamp,
      canvasSteps,
      cycleCanvasSteps,
      canvasAngle,
      cycleCanvasAngle,
      canvasSpeed,
      cycleCanvasSpeed,
      canvasAnimated,
      toggleCanvasAnimated,
      shuffleCanvas,
      patternStyle,
      setPatternStyle,
      cyclePatternStyle,
      patternDensity,
      cyclePatternDensity,
      patternSpeed,
      cyclePatternSpeed,
      patternDisc,
      cyclePatternDisc,
      baseColor,
      setBaseColor,
    }),
    [
      background,
      setBackground,
      gradientAxis,
      setGradientAxis,
      gradientAngle,
      cycleGradientAngle,
      gradientShape,
      cycleGradientShape,
      gradientPosition,
      cycleGradientPosition,
      radialShape,
      cycleRadialShape,
      radialSize,
      cycleRadialSize,
      canvasStyle,
      setCanvasStyle,
      canvasRamp,
      setCanvasRamp,
      canvasSteps,
      cycleCanvasSteps,
      canvasAngle,
      cycleCanvasAngle,
      canvasSpeed,
      cycleCanvasSpeed,
      canvasAnimated,
      toggleCanvasAnimated,
      shuffleCanvas,
      patternStyle,
      setPatternStyle,
      cyclePatternStyle,
      patternDensity,
      cyclePatternDensity,
      patternSpeed,
      cyclePatternSpeed,
      patternDisc,
      cyclePatternDisc,
      baseColor,
      setBaseColor,
    ],
  );

  return (
    <BackgroundContext.Provider value={value}>
      {renderBackground(background, {
        gradientAxis,
        gradientAngle,
        gradientShape,
        gradientPosition,
        radialShape,
        radialSize,
        canvasStyle,
        canvasRamp,
        canvasSteps,
        canvasAngle,
        canvasSpeed,
        canvasAnimated,
        canvasSeed,
        patternStyle,
        patternDensity,
        patternSpeed,
        patternDisc,
        baseColor,
      })}
      {children}
    </BackgroundContext.Provider>
  );
}

"use client";

import { PaletteIcon, PauseIcon, PlayIcon, ProhibitIcon, ShuffleIcon, SparkleIcon, SquaresFourIcon } from "@phosphor-icons/react";
import { type BackgroundType, CANVAS_STYLES, RAMP_AXES, useBackground } from "@/components/background-provider";
import { ANIMATED_PATTERNS, DISC_PATTERNS, PATTERN_STYLES, type PatternStyle } from "@/components/pattern-background";
import { cn } from "@/lib/utils";

const options: {
  value: BackgroundType;
  label: string;
  Icon: typeof PaletteIcon;
}[] = [
  {
    value: "gradient",
    label: "Gradient",
    Icon: PaletteIcon,
  },
  {
    value: "canvas",
    label: "Canvas",
    Icon: SparkleIcon,
  },
  {
    value: "pattern",
    label: "Pattern",
    Icon: SquaresFourIcon,
  },
  {
    value: "none",
    label: "None",
    Icon: ProhibitIcon,
  },
];

/** Compact glyphs for the gradient center + radial size. */
const POS_SYMBOL: Record<string, string> = {
  "50% 50%": "•",
  "0% 0%": "↖",
  "100% 0%": "↗",
  "100% 100%": "↘",
  "0% 100%": "↙",
};
const SIZE_SHORT: Record<string, string> = {
  "farthest-corner": "f-cnr",
  "farthest-side": "f-side",
  "closest-corner": "c-cnr",
  "closest-side": "c-side",
};

const segmentButton = "inline-flex h-7 items-center justify-center rounded-md transition-colors";

/**
 * Compact segmented control to switch the site-wide background. Gradient exposes a ramp-axis +
 * angle picker; Canvas exposes style (gradient / lava / circle), ramp axis, steps-per-side, angle,
 * speed, shuffle, and animate. Great for previewing how glass components read against each backdrop.
 */
export function BackgroundSwitcher() {
  const {
    background,
    setBackground,
    gradientAxis,
    setGradientAxis,
    gradientAngle,
    cycleGradientAngle,
    gradientShape,
    cycleGradientShape,
    gradientPosition,
    cycleGradientPosition,
    radialShape,
    cycleRadialShape,
    radialSize,
    cycleRadialSize,
    canvasStyle,
    setCanvasStyle,
    canvasRamp,
    setCanvasRamp,
    canvasSteps,
    cycleCanvasSteps,
    canvasAngle,
    cycleCanvasAngle,
    canvasSpeed,
    cycleCanvasSpeed,
    canvasAnimated,
    toggleCanvasAnimated,
    shuffleCanvas,
    patternStyle,
    setPatternStyle,
    patternDensity,
    cyclePatternDensity,
    patternSpeed,
    cyclePatternSpeed,
    patternDisc,
    cyclePatternDisc,
    baseColor,
    setBaseColor,
  } = useBackground();

  const active = "bg-foreground/10 text-foreground";
  const idle = "text-muted-foreground hover:bg-foreground/5 hover:text-foreground";
  const nextStyle = CANVAS_STYLES[(CANVAS_STYLES.indexOf(canvasStyle) + 1) % CANVAS_STYLES.length];

  return (
    <div
      role="group"
      aria-label="Background style"
      className="hidden items-center gap-0.5 rounded-lg border border-[var(--glass-border)] p-0.5 sm:flex"
    >
      {options.map(({ value, label, Icon }) => (
        <button
          key={value}
          type="button"
          title={`${label} background`}
          aria-label={`${label} background`}
          aria-pressed={background === value}
          onClick={() => setBackground(value)}
          className={cn(segmentButton, "w-7", background === value ? active : idle)}
        >
          <Icon className="h-4 w-4" weight={background === value ? "fill" : "regular"} />
        </button>
      ))}

      {background === "gradient" && (
        <div className="flex items-center gap-0.5 border-[var(--glass-border)] border-l pl-0.5" role="group" aria-label="Gradient ramp + angle">
          {RAMP_AXES.map((axis) => (
            <button
              key={axis}
              type="button"
              title={`${axis} gradient`}
              aria-label={`${axis} gradient`}
              aria-pressed={gradientAxis === axis}
              onClick={() => setGradientAxis(axis)}
              className={cn(segmentButton, "w-7 text-[11px] font-semibold uppercase", gradientAxis === axis ? active : idle)}
            >
              {axis[0]}
            </button>
          ))}
          {/* Shape: linear | radial | conic */}
          <button
            type="button"
            title={`Gradient shape: ${gradientShape} — click to change`}
            aria-label={`Gradient shape ${gradientShape}, click to change`}
            onClick={cycleGradientShape}
            className={cn(segmentButton, "px-1.5 text-[10px] font-semibold capitalize", active)}
          >
            {gradientShape}
          </button>
          {/* Center position — radial + conic */}
          {(gradientShape === "radial" || gradientShape === "conic") && (
            <button
              type="button"
              title={`Center — ${gradientPosition}`}
              aria-label={`Gradient center ${gradientPosition}`}
              onClick={cycleGradientPosition}
              className={cn(segmentButton, "w-7 text-[13px]", idle)}
            >
              {POS_SYMBOL[gradientPosition] ?? "•"}
            </button>
          )}
          {/* Radial shape + size */}
          {gradientShape === "radial" && (
            <>
              <button
                type="button"
                title={`Radial shape: ${radialShape}`}
                aria-label={`Radial shape ${radialShape}`}
                onClick={cycleRadialShape}
                className={cn(segmentButton, "px-1.5 text-[10px] font-semibold capitalize", idle)}
              >
                {radialShape}
              </button>
              <button
                type="button"
                title={`Radial size: ${radialSize}`}
                aria-label={`Radial size ${radialSize}`}
                onClick={cycleRadialSize}
                className={cn(segmentButton, "px-1.5 text-[10px] font-semibold", idle)}
              >
                {SIZE_SHORT[radialSize] ?? radialSize}
              </button>
            </>
          )}
          {/* Angle — not meaningful for radial (fixed center) */}
          {gradientShape !== "radial" && (
            <button
              type="button"
              title={`Rotate gradient — ${gradientAngle}°`}
              aria-label={`Rotate gradient, currently ${gradientAngle} degrees`}
              onClick={cycleGradientAngle}
              className={cn(segmentButton, "px-1.5 text-[10px] font-semibold tabular-nums", idle)}
            >
              {gradientAngle}°
            </button>
          )}
        </div>
      )}

      {background === "canvas" && (
        <div className="flex items-center gap-0.5 border-[var(--glass-border)] border-l pl-0.5" role="group" aria-label="Canvas controls">
          {/* Style: gradient | lava | circle */}
          <button
            type="button"
            title={`Canvas style: ${canvasStyle} — click for ${nextStyle}`}
            aria-label={`Canvas style ${canvasStyle}, click to change`}
            onClick={() => setCanvasStyle(nextStyle)}
            className={cn(segmentButton, "px-1.5 text-[10px] font-semibold capitalize", active)}
          >
            {canvasStyle}
          </button>
          {/* Ramp axis (lightness = "linear") */}
          {RAMP_AXES.map((axis) => (
            <button
              key={axis}
              type="button"
              title={`${axis === "lightness" ? "linear (lightness)" : axis} ramp`}
              aria-label={`${axis} ramp`}
              aria-pressed={canvasRamp === axis}
              onClick={() => setCanvasRamp(axis)}
              className={cn(segmentButton, "w-7 text-[11px] font-semibold uppercase", canvasRamp === axis ? active : idle)}
            >
              {axis[0]}
            </button>
          ))}
          {/* Steps per side (4–12) */}
          <button
            type="button"
            title={`Steps per side — ${canvasSteps}`}
            aria-label={`Steps per side, currently ${canvasSteps}`}
            onClick={cycleCanvasSteps}
            className={cn(segmentButton, "px-1.5 text-[10px] font-semibold tabular-nums", idle)}
          >
            {canvasSteps}×
          </button>
          {/* Angle — gradient style only */}
          {canvasStyle === "gradient" && (
            <button
              type="button"
              title={`Gradient angle — ${canvasAngle}°`}
              aria-label={`Gradient angle, currently ${canvasAngle} degrees`}
              onClick={cycleCanvasAngle}
              className={cn(segmentButton, "px-1.5 text-[10px] font-semibold tabular-nums", idle)}
            >
              {canvasAngle}°
            </button>
          )}
          {/* Speed — only meaningful while animating */}
          {canvasAnimated && (
            <button
              type="button"
              title={`Animation speed — ${canvasSpeed}×`}
              aria-label={`Animation speed, currently ${canvasSpeed} times`}
              onClick={cycleCanvasSpeed}
              className={cn(segmentButton, "px-1.5 text-[10px] font-semibold tabular-nums", idle)}
            >
              {canvasSpeed}×
            </button>
          )}
          <button
            type="button"
            title="Shuffle canvas"
            aria-label="Shuffle canvas style, ramp, and layout"
            onClick={shuffleCanvas}
            className={cn(segmentButton, "w-7", idle)}
          >
            <ShuffleIcon className="h-4 w-4" />
          </button>
          <button
            type="button"
            title={canvasAnimated ? "Pause animation" : "Animate canvas"}
            aria-label={canvasAnimated ? "Pause canvas animation" : "Animate canvas"}
            aria-pressed={canvasAnimated}
            onClick={toggleCanvasAnimated}
            className={cn(segmentButton, "w-7", canvasAnimated ? active : idle)}
          >
            {canvasAnimated ? <PauseIcon className="h-4 w-4" weight="fill" /> : <PlayIcon className="h-4 w-4" />}
          </button>
        </div>
      )}

      {background === "pattern" && (
        <div className="flex items-center gap-0.5 border-[var(--glass-border)] border-l pl-0.5" role="group" aria-label="Pattern controls">
          {/* Direct pick — jump straight to any pattern instead of cycling through all of them. */}
          <select
            value={patternStyle}
            onChange={(e) => setPatternStyle(e.target.value as PatternStyle)}
            title="Pattern — pick one"
            aria-label="Pattern style"
            className={cn(segmentButton, "cursor-pointer bg-transparent px-1.5 text-[10px] font-semibold capitalize outline-none", active)}
          >
            {PATTERN_STYLES.map((s) => (
              <option key={s} value={s} className="bg-background text-foreground capitalize">
                {s}
              </option>
            ))}
          </select>
          <button
            type="button"
            title={`Density: ${patternDensity} — click to change`}
            aria-label={`Density ${patternDensity}, click to change`}
            onClick={cyclePatternDensity}
            className={cn(segmentButton, "px-1.5 text-[10px] font-semibold capitalize", idle)}
          >
            {patternDensity}
          </button>
          {ANIMATED_PATTERNS.has(patternStyle) && (
            <button
              type="button"
              title={`Speed: ${patternSpeed === 0 ? "static" : `${patternSpeed}s`} — click to change`}
              aria-label={`Animation speed ${patternSpeed === 0 ? "static" : `${patternSpeed} seconds`}, click to change`}
              onClick={cyclePatternSpeed}
              className={cn(segmentButton, "px-1.5 text-[10px] font-semibold tabular-nums", patternSpeed === 0 ? active : idle)}
            >
              {patternSpeed === 0 ? "Static" : `${patternSpeed}s`}
            </button>
          )}
          {DISC_PATTERNS.has(patternStyle) && (
            <button
              type="button"
              title={`Sun/moon placement: ${patternDisc} — click to change`}
              aria-label={`Sun and moon placement ${patternDisc}, click to change`}
              onClick={cyclePatternDisc}
              className={cn(segmentButton, "w-7 text-[11px] font-semibold uppercase", idle)}
            >
              {patternDisc[0]}
            </button>
          )}
        </div>
      )}

      {background === "none" && (
        <div className="flex items-center gap-1 border-[var(--glass-border)] border-l pl-1.5" role="group" aria-label="Base color">
          <label
            className="relative inline-flex h-6 w-6 cursor-pointer items-center justify-center"
            title="Base color — pick to override the themed default"
          >
            <span className="sr-only">Base color</span>
            <span
              aria-hidden="true"
              className="h-4 w-4 rounded-full border border-[var(--glass-border)]"
              style={{
                background: baseColor ?? "oklch(0.85 0.03 var(--glass-tint-h))",
              }}
            />
            <input
              type="color"
              value={baseColor ?? "#101014"}
              onChange={(e) => setBaseColor(e.target.value)}
              className="absolute inset-0 cursor-pointer opacity-0"
            />
          </label>
          {baseColor && (
            <button
              type="button"
              title="Reset base color to the themed default"
              aria-label="Reset base color to theme default"
              onClick={() => setBaseColor(null)}
              className={cn(segmentButton, "px-1.5 text-[10px] font-semibold", idle)}
            >
              Theme
            </button>
          )}
        </div>
      )}
    </div>
  );
}
